def main():
    N = int(input())
    S = input()
    C = list(map(int, input().split()))

    ANS = 10**50

    for i in range(N - 1):
        if S[i] != S[i + 1]:
            cost = min(C[i], C[i + 1])
        else:
            cost = C[i] + C[i + 1]
        ANS = min(ANS, cost)

    print(ANS)
